    # Calculate tau(n)
    tau = 1
    for exponent in factors.values():
        tau *= (exponent + 1)

    # Check if tau(n) is twice an odd integer (tau = 2 * M, M odd)
    # This means tau must be even, and tau / 2 must be odd.
    if tau % 2 != 0:
        return False

    M = tau // 2
    if M % 2 == 1:
        return True
    else:
        return False

