def check_exotic(n):
    if n <= 0:
        return False

    factors = get_prime_factors(n)

    # Check the condition: exactly one exponent e such that e = 4k+1, and all others are even.
    # Equivalent to: exactly one exponent e such that e+1 = 2 * odd_number.

    odd_power_count = 0

    for e in factors.values():
        # Check if e is of the form 4k+1
        if (e % 4) == 1:
            odd_power_count += 1
        # Check if e is even
        elif e % 2 == 0:
            pass # This is allowed
        # Check if e is 2 or 6 or 10 etc. (e = 4k+2) -> e+1 = 4k+3 (odd)
        # This is not allowed based on the derivation. e must be even OR e=4k+1.
        else:
            # e is odd, and e != 4k+1. E.g., e=3, 7, 11...
            # If e=3, e+1=4. tau(n) has a factor of 4, so it is divisible by 4, not 2*odd.
            return False

    # We require exactly one exponent e such that e+1 is 2 * odd.
    # Since we checked for e % 4 == 1, we are checking e+1 = 4k+2 = 2(2k+1).

    # If there are no such exponents, tau(n) is odd (or 1), so it's not 2*M.
    if odd_power_count == 0:
        return False

    # If there is exactly one such exponent, and all others are even, we are good.
    if odd_power_count == 1:
        return True

    return False # If odd_power_count > 1


